78	/// compress data from opened file into output file
79	int compress(int in_fd, int out_fd, int level, off_t & pointer, const struct stat & info_in)
80	{
81	    off_t in_offset = 0;
82	
83	    /// mmap files
84	    char * input = static_cast<char*>(mmap(nullptr, info_in.st_size, PROT_READ, MAP_PRIVATE, in_fd, 0));
85	    if (input == MAP_FAILED)
86	    {
87	        perror(nullptr);
88	        return 1;
89	    }
90	
91	    /// Create context
92	    ZSTD_CCtx * cctx = ZSTD_createCCtx();
93	    if (cctx == nullptr)
94	    {
95	        std::cerr << "Error (ZSTD): failed to create compression context" << std::endl;
96	        return 1;
97	    }
98	
99	    size_t check_result;
100	
101	    /// Set level and enable checksums
102	    check_result = ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, level);
103	    if (ZSTD_isError(check_result))
104	    {
105	        std::cerr << "Error (ZSTD): " << check_result << " " << ZSTD_getErrorName(check_result) << std::endl;
106	        return 1;
107	    }
108	    check_result = ZSTD_CCtx_setParameter(cctx, ZSTD_c_checksumFlag, 1);
109	    if (ZSTD_isError(check_result))
110	    {
111	        std::cerr << "Error (ZSTD): " << check_result << " " << ZSTD_getErrorName(check_result) << std::endl;
112	        return 1;
113	    }
114	
115	    /// limits for size of block to prevent high memory usage or bad compression
116	    off_t max_block_size = 1ull<<27;
117	    off_t min_block_size = 1ull<<23;
118	    off_t size = 0;
119	    off_t current_block_size = 0;
120	
121	    /// Create buffer for compression
122	    /// Block can't become much bigger after compression.
123	    char * output = static_cast<char*>(
124	        mmap(nullptr, 2 * max_block_size,
125	            PROT_READ | PROT_WRITE, MAP_ANON | MAP_PRIVATE,
126	            -1,
127	            0)
128	        );
129	    if (output == MAP_FAILED)
130	    {
131	        perror(nullptr);
132	        return 1;
133	    }
134	    if (-1 == lseek(out_fd, 0, SEEK_END))
135	    {
136	        perror(nullptr);
137	        return 1;
138	    }
139	
140	    /// Compress data
141	    while (in_offset < info_in.st_size)
142	    {
143	        /// take blocks of maximum size
144	        /// optimize last block (it can be bigger, if it is not too huge)
145	        if (info_in.st_size - in_offset < max_block_size || info_in.st_size - in_offset < max_block_size + min_block_size)
146	            size = info_in.st_size - in_offset;
147	        else
148	            size = max_block_size;
149	
150	        /// Compress data or exit if error happens
151	        if (0 != doCompress(input, output, in_offset, current_block_size, size, ZSTD_compressBound(size), cctx))
152	        {
153	            if (0 != munmap(input, info_in.st_size))
154	                perror(nullptr);
155	            if (0 != munmap(output, 2 * max_block_size))
156	                perror(nullptr);
157	            return 1;
158	        }
159	
160	        /// Save data into file and refresh pointer
161	        if (current_block_size != write_data(out_fd, output, current_block_size))
162	        {
163	            perror(nullptr);
164	            return 1;
165	        }
166	        pointer += current_block_size;
167	        printf("...block compression rate: %.2f%%\n", static_cast<float>(current_block_size) / size * 100);
168	        current_block_size = 0;
169	    }
170	
171	    if (0 != munmap(input, info_in.st_size) ||
172	        0 != munmap(output, 2 * max_block_size))
173	    {
174	        perror(nullptr);
175	        return 1;
176	    }
177	    return 0;
178	}
