222	int compressFiles(char* filenames[], int count, int output_fd, int level, const struct stat& info_out)
223	{
224	    MetaData metadata;
225	    size_t sum_file_size = 0;
226	    metadata.number_of_files = htole64(count);
227	    off_t pointer = info_out.st_size;
228	
