230	    FileData* files_data = new FileData[count];
231	    char * names[count];
232	    for (int i = 0; i < count; ++i)
233	    {
234	        printf("Compressing: %s\n", filenames[i]);
235	
236	        int input_fd = open(filenames[i], O_RDONLY);
237	        if (input_fd == -1)
238	        {
239	            perror(nullptr);
240	            delete [] files_data;
241	            return 1;
242	        }
243	
244	        /// Remember information about file name
245	        /// This should be made after the file is opened
246	        /// because filename should be extracted from path
247	        names[i] = strrchr(filenames[i], '/');
248	        if (names[i])
249	            ++names[i];
250	        else
251	            names[i] = filenames[i];
252	        size_t nlen = strlen(names[i]) + 1;
253	        files_data[i].name_length = htole64(nlen);
254	        sum_file_size += nlen;
255	
256	        /// read data about input file
257	        struct stat info_in;
258	        if (0 != fstat(input_fd, &info_in))
259	        {
260	            perror(nullptr);
261	            delete [] files_data;
262	            return 1;
263	        }
264	
265	        if (info_in.st_size == 0)
266	        {
267	            printf("...empty file, skipped.\n");
268	            continue;
269	        }
270	
271	        std::cout << "Size: " << info_in.st_size << std::endl;
272	
273	        /// Save umask
274	        files_data[i].umask = htole64(info_in.st_mode);
275	
276	        /// Remember information about uncompressed size of file and
277	        /// start of it's compression version
278	        files_data[i].uncompressed_size = htole64(info_in.st_size);
279	        files_data[i].start = htole64(pointer);
280	
281	        /// Compressed data will be added to the end of file
282	        /// It will allow to create self extracting executable from file
283	        if (0 != compress(input_fd, output_fd, level, pointer, info_in))
284	        {
285	            perror(nullptr);
286	            delete [] files_data;
287	            return 1;
288	        }
289	
290	        /// This error is less important, than others.
291	        /// If file cannot be closed, in some cases it will lead to
292	        /// error in other function that will stop compression process
293	        if (0 != close(input_fd))
294	            perror(nullptr);
295	
296	        files_data[i].end = htole64(pointer);
297	    }
298	
299	    /// save location of files information
300	    metadata.start_of_files_data = htole64(pointer);
301	
302	    if (0 != saveMetaData(names, count, output_fd, metadata, files_data, pointer, sum_file_size))
303	    {
304	        delete [] files_data;
305	        return 1;
306	    }
307	
308	    delete [] files_data;
309	    return 0;
310	}
