312	int copy_decompressor(int input_fd, int decompressor_size, int output_fd)
313	{
314	    const ssize_t buf_size = 1ul<<19;
315	    auto buf_memory = std::make_unique<char[]>(buf_size);
316	    char * buf = buf_memory.get();
317	
318	    while (decompressor_size > 0)
319	    {
320	        ssize_t read_size = decompressor_size > buf_size ? buf_size : decompressor_size;
321	        ssize_t n = read_data(input_fd, buf, read_size);
322	        if (n < read_size)
323	        {
324	            perror(nullptr);
325	            return 1;
326	        }
327	        decompressor_size -= n;
328	
329	        if (n != write_data(output_fd, buf, n))
330	        {
331	            perror(nullptr);
332	            return 1;
333	        }
334	    }
335	
336	    return 0;
337	}
