418	const char * get_param(int argc, char * const argv[], const char * name)
419	{
420	    if (nullptr == name || name[0] == 0)
421	        return nullptr;
422	
423	    for (int i = 1; i < argc; ++i)
424	    {
425	        const char * arg = argv[i];
426	        if (arg[0] != '-' || arg[1] != '-')
427	            return nullptr;
428	
429	        size_t arg_len = strlen(arg);
430	        size_t name_len = strlen(name);
431	
432	        const char * eq = strchr(arg + 2, '=');
433	        if (nullptr == eq)
434	            eq = arg + arg_len;
435	
436	        if (name_len != static_cast<size_t>(eq - arg - 2))
437	            continue;
438	
439	        if (0 == memcmp(name, arg + 2, name_len))
440	            return *eq == 0 ? eq : eq + 1;
441	    }
442	
443	    return nullptr;
444	}
